INSERT INTO public.issue (id, project_id, sequence_number, type_id, column_id, title, description, priority, start_date, due_date, "position", created_at, updated_at, assignee_user_id, delegate_user_id, initiative_id, archived_at, share_token, parent_id, share_extended, cycle_id, estimate_points, estimate_minutes) VALUES (57, 1, 84, 9, 4, 'The live-iteration batch: countdown model, colons, Readex Pro, locale-driven rules', 'Owner-driven, 2026-10-14 (no brief; the session''s own rulings): the countdown''s per-digit dim model (live zeros bright, padding zeros dim, the left-to-right spent cascade, seconds never), the fast linear tick fades against the overlay''s own 200ms swaps, the drawn colon dots with the ink compensation for the narrow 1, the row-time colon on margins with the next-prayer brightening, LTR rows under ar, Readex Pro replacing Noto Sans Arabic (natively bundled, the record table per locale, the RTL set and digit table as data), the ar line box as record data, the native date and sentence digits, the mirrored chevrons, the Extras list gap, the bar track on the dim colour, the slim tip, show-seconds default on, the mock''s Isha runway, and four pixel rulings recorded (the timer block 54, the name 17 lifted 2, the gap under the bar 48); the numeral ruling''s boundary recorded: the countdown and its bar keep Latin, every other sentence and value takes the locale''s digits

Status note: 2026-10-14, audited: 2.0.250 carries the batch (32 files, 5557 tests, 100 percent on statements, branches, functions and lines), the two-reviewer audit over the range, the dev build rebuilt with the native Readex faces; the locale rule made data - RTL membership, native-digit tables and the typography records replace every ar branch', NULL, NULL, NULL, 36000, '2026-10-18 23:35:56.452892+00', '2026-10-19 02:54:08.176952+00', NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL);
