INSERT INTO public.issue (id, project_id, sequence_number, type_id, column_id, title, description, priority, start_date, due_date, "position", created_at, updated_at, assignee_user_id, delegate_user_id, initiative_id, archived_at, share_token, parent_id, share_extended, cycle_id, estimate_points, estimate_minutes) VALUES (338, 1, 338, NULL, 4, 'Step 1: The API''s real expected times recorded, then the static fall-back proof closed', 'Code, 2 points. Curl the API first (key from ~/.config/athan/.api_key into the process env only, never printed) and transcribe the 24-26 Oct six times, the 24-25 night rows and Fajr 25 Oct GMT into a ticket comment. Then run yarn test:tz and the fall/budget suite filters, write the three gap tests seeded from those real rows with the clock mocked, each proven able to fail by a mutation pass (flip the guarded logic, watch it fail, revert), yarn validate green. Deadline 23:00 BST. Plan doc T-337, Step 1.', NULL, NULL, NULL, 9000, '2026-10-24 20:51:43.951411+00', '2026-10-24 21:20:08.165323+00', NULL, NULL, NULL, NULL, NULL, 337, false, NULL, 2, NULL);
