INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (1213, 37, 'activity', 'owner', NULL, 'description', '2026-10-19 02:31:04.791226+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "OWNER RULING 2026-10-16: a new (or never-toggled) user starts with a clean app - Show Hijri date, Show seconds, Show time passed and Show countdown bar all OFF by default; a user who manually toggled any switch keeps their stored choice untouched, no migration (the row-105 law, the owner''s explicit confirmation). Three of the four were already off; Show time passed defaulted ON and flipped\n\nStatus note: 2026-10-16, landed direct at 2.0.837 by the owner''s order (all gates green, 5692 tests, 100 percent): the atom''s default pin false, the defaults suite re-pinned, and the prayer-page suite seeding the ago line through the shared harness helper beside the bar''s (the off-behaviour test unchanged, setting the atom itself)"}}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (1227, 42, 'activity', 'owner', NULL, 'title', '2026-10-19 02:31:04.864975+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "Agent tooling: the Vercel performance skill, mobile-mcp and the maestro server on"}, "from": {"value": "#107 Agent tooling: the Vercel performance skill, mobile-mcp and the maestro server on"}}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (1228, 42, 'activity', 'owner', NULL, 'description', '2026-10-19 02:31:04.864975+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "OWNER ORDER 2026-10-15 late evening, landed direct in a parallel worktree lane (no shared-tree conflict with the 103/104/106 executors): (1) the Vercel `react-native-skills` package (35+ performance rules across 13 categories, January 2026, MIT, fetched verbatim from vercel-labs/agent-skills) joins `.agents/skills/` beside Software Mansion''s `react-native-best-practices` - verified DIFFERENT skills before adding (the Vercel set is the performance rules; the Mansion skill is the New Architecture patterns family), and both are now named in the load path so every session and worker reaches for them on React Native code work; (2) `mobile-mcp` and the `maestro` MCP flip `enabled: true` in `opencode.json` so the owner''s next sessions start with them; `expo` stays off by the owner''s word; (3) both AGENTS.md routing paragraphs carry the new truth\n\nStatus note: 2026-10-15, landed direct at 2.0.792 by the owner''s order"}}', NULL);
