INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (1350, 83, 'activity', 'owner', NULL, 'title', '2026-10-19 02:31:05.459015+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "A reschedule inside 30s of an armed reminder cancels it"}, "from": {"value": "#55 A reschedule inside 30s of an armed reminder cancels it"}}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (1351, 83, 'activity', 'owner', NULL, 'description', '2026-10-19 02:31:05.459015+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "Defect found by the row 38 external adjudication (an external branch, `04-surfaces.md` section 2): a scheduling pass that runs within 30 seconds before an armed reminder fires cancels it (`stores/notifications.ts:1040-1051`, `:1130-1139`). Independent of localisation. Notification scheduling logic, ask-first by rule, so it gets its own job\n\nStatus note: 2026-10-11, audited: a pass inside the final 30 seconds before an armed reminder now keeps it armed, no re-arm and no cancel, record intact; unarmed imminent reminders still skip and past ones still clean up; red-green in `stores/__tests__/reminderImminentKeepAlive.test.ts` and clock-proven on the 3T production build (cold launch at T minus 20 s left the target byte-identical and it fired once at T plus 208 ms with the armed content; the mock''s per-download re-seed had made the in-harness proof impossible, ruled onto the production vehicle by the owner). Three-pass audit, two blind findings fixed (`bb747947` pins the record guard against mutation, `097a7bcd` restores the docblock word); fix merged as `6dc9125b` into `09c13e46` (2.0.6, hook 5297 passed, coverage 100%), step 2 as `fc568fa7` into `eb3c2605` (2.0.12). Landed through 2.0.14. Group: notifications scheduling, `stores/notifications.ts` shared with row 39''s convergence work when it plans; same-group rows serialize. Queue order flipped by the owner: this row runs before row 39 (D39)\n\nNeeds first: #53"}}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (1255, 51, 'activity', 'owner', NULL, 'description', '2026-10-19 02:31:04.988488+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "OWNER ASK 2026-10-15: the owner verifies the Ramadan face still renders after the lettered work. The session enables the force flag LOCALLY on the dev build (never committed; the gate patch dies with the tree restore) and the owner reads the phone; the owner''s read is the whole ticket. No production change; a defect the owner finds opens its own row\n\nStatus note: 2026-10-15, the owner''s read: the Ramadan face confirmed in English and Arabic on the prod-armed dev build (decorations, mosque variant, settings toggle); no defect found, no production code changed; the local arm (the gate patch on `shared/time.ts` plus Metro on the force flag) dies with the session''s tree restore"}}', NULL);
