INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (1336, 78, 'activity', 'owner', NULL, 'description', '2026-10-19 02:31:05.379323+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "Owner ask, 2026-10-12: modals can grow taller than the screen in longer languages; the owner asked that every modal be capped, with the growing region scrolling when content exceeds the max. AMENDED 2026-10-12 (owner interview, D70 to D73): the modal family only - no bottom sheet changes at all; Help already capped, stays untouched; WhatsNew''s list gets the Help scroll pattern (share 0.62); Update''s message bounded too, never engaging at today''s copy (D71, the report names it so the owner can strike it); no pixel moves at today''s content\n\nStatus note: 2026-10-12, audited and pushed: both growing modal regions bounded - WhatsNew''s release list and Update''s message scroll inside 0.62 of the window (Help''s own share), fixed parts pinned outside, no pixel moves at today''s content; Help untouched, no bottom sheet touched (D70); Update''s bound never engages at today''s copy (D71)\n\nNeeds first: #39"}}', NULL);
