INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (2025, 230, 'activity', 'owner', NULL, 'description', '2026-10-19 09:37:55.639591+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "PR: https://github.com/expo/expo/pull/50581\n\nMonitoring row for PR `expo/expo#50581`, tracked in `ai/UPSTREAM-PRS.md` (row: expo-background-task). The PR makes the background network requirement configurable; the local patch dies at the first re-pin past its release. Opened 2026-10-09, open and unmerged at the 2026-10-17 re-check."}}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (2026, 231, 'activity', 'owner', NULL, 'description', '2026-10-19 09:37:55.707003+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "PR: https://github.com/expo/expo/pull/51290\n\nMonitoring row for PR `expo/expo#51290`, tracked in `ai/UPSTREAM-PRS.md` (related upstream PRs table). The PR fixes the Android Glance converter dropping the `fillMaxWidth` fraction; nothing in this repo changes until it merges, and the proportional-layout workaround simplifies only at the owner''s say."}}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (2027, 232, 'activity', 'owner', NULL, 'description', '2026-10-19 09:37:55.756477+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "PR: https://github.com/expo/expo/pull/51292\n\nMonitoring row for PR `expo/expo#51292`, tracked in `ai/UPSTREAM-PRS.md` (row: expo-widgets). The PR adds the `openApp` option to the Android widget Button; at the first re-pin past its release the openApp half of the widgets patch dies."}}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (2028, 239, 'activity', 'owner', NULL, 'description', '2026-10-19 09:37:55.80012+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "PR: https://github.com/expo/expo/pull/51793\n\nMonitoring row for PR `expo/expo#51793`, tracked in `ai/UPSTREAM-PRS.md` (row: expo-widgets). The PR exposes the device locale to widget JS runtimes through a `__expoWidgetDeviceLocale` global; when a published release carries it, board row #233 deletes the local patch''s device-locale hunks and the ledger entry moves to shipped. Filed 2026-10-19 from the fork, one commit, four code files plus its changeset."}}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (2029, 16, 'activity', 'owner', NULL, 'title', '2026-10-19 13:03:51.218919+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "Help modal: a widgets support question"}, "from": {"value": "Settings: a Widgets option that opens the OS widget gallery at our section"}}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (2030, 16, 'activity', 'owner', NULL, 'description', '2026-10-19 13:03:51.218919+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "Goal: one new question in the help modal about widget support, answered in one short sentence, with nothing anywhere teaching how to add a widget.\n\nWhere: shared/help.ts (HELP_ENTRIES), the six catalogues shared/i18n/{en,ar,ms,so,hi,th}.ts with the catalog lock, the help coverage shared/__tests__/help.test.ts, and the help modal itself (components/modals/Help.tsx), which needs no change.\n\nAcceptance:\n- [ ] The help modal lists one new question about widget support, appended after the last entry, following HELP_ENTRIES'' own pattern: a question key plus one answer key per platform, no steps, no action.\n- [ ] The English question and answer are each one short sentence, and the answer says only whether widgets are supported: no add-a-widget path or instruction appears in any locale.\n- [ ] All six catalogues carry the new keys and yarn i18n:lock is re-taken with the catalog lock test green.\n- [ ] shared/__tests__/help.test.ts is red before the entry exists and green after it, inside yarn validate.\n- [ ] The help modal on the 3T and on the owner''s iPhone shows the new question, and each read lands as a ticket comment."}}', NULL);
