INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (2531, 271, 'activity', 'owner', NULL, 'subtask_add', '2026-10-20 03:59:18.198877+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"id": 279, "value": "T-279"}}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (2542, 280, 'activity', 'owner', NULL, 'description', '2026-10-20 04:13:25.749858+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "Goal: name whether the Duo''s open pose should render the app portrait-tall instead of landscape-spanned, with both options seen and priced, for the owner''s pick.\n\nWhere: the iPhone Duo simulator (Lane 2''s until row 271 returns), Apple''s Duo and orientation documentation, and row 271''s branch as Option A realized.\n\nOWNER QUESTION 2026-10-20: the app is honestly vertical - why would landscape be better? What if the Duo''s open pose is treated as a tall screen, the app rendering top down on both panels instead of across them? Keep it as an option, investigate: how much effort it saves, what it looks like, whether it is actually worth it.\n\nAGENT-RULED (lead, 2026-10-20): row 271''s landscape gate continues to its close as Option A - it is nearly done, and if Option B wins its gate comes out in one revert. This row runs after 271 returns (the Duo simulator is theirs until then) and changes no code: it renders, measures, and tables.\n\nAcceptance:\n- [ ] Option A documented from row 271''s real landed shape: what it looks like on the open pose, what it cost in code and native surface, its maintenance and layout risks\n- [ ] Option B named and rendered: whether iOS allows a portrait-tall presentation on the Duo''s inner display (rotated device or otherwise), and what the app looks like top-down at that geometry - simulator renders, never committed\n- [ ] the effort comparison tabled: code surface, native work, layout risk, and what each option does to the black bars and the background edge to edge\n- [ ] screenshots of BOTH options on the row, labelled A and B, so the owner reads the comparison from the board whenever they return\n- [ ] a recommendation argued twice, tabled to the owner for the pick - nothing decided in this row, no code changed, and the run never waits for the pick: work continues past this row the moment the comparison is posted"}}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (2532, 271, 'activity', 'owner', NULL, 'estimate', '2026-10-20 03:59:18.224011+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "8"}, "from": {"value": "6"}, "subject": {"value": "points"}}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (2533, 271, 'comment', 'owner', 'Step 2''s reading found the live-unfold path keeps the letterbox until relaunch: UIKit never re-asks the supported orientations when the window changes panels. The plan gains Step 2b (the pre-designed re-ask branch, bounded, reverted if both attempts fail); the row''s points move to 8.', NULL, '2026-10-20 03:59:18.240255+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
