INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (2648, 276, 'comment', 'owner', 'The XS read of the shipped Design 1 (from shipped-design.png, measured by the vision pass): the button''s bottom edge sits 34.0pt above the screen bottom - exactly today''s dots-bottom anchor on this phone - with 21pt of clear air to the home indicator; the button keeps its full 43pt size; both dots sit on the button''s vertical midline within half a pixel, 8pt either side; nothing else occupies the foot of the screen, the whole band between the last row and the bar is empty gradient, and the prototype''s D1/10 badge is gone with the switcher. The readings match design-01.png point for point within antialiasing. The mock Release 2.2.1 build (paid-team signing, inline team id) is installed on the phone, curing the ten-design prototype build it carried.', NULL, '2026-10-20 06:33:14.913528+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
