INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (2701, 272, 'comment', 'owner', 'The first rewrite missed one class the gate knows: a device serial held only in this machine''s identifier denylist (entry 26, two old runbook records), plus five historical design renders the media rule refuses. The second run scrubbed that serial, stripped those five images from history, and the gate''s own history scan now exits 0 on every branch tip; the whole local object database reads zero hits, every identity reads Athan <athan@athan.uk>, lane/280 and the two build worktrees are re-pointed, and yarn validate is green at 76bc6fff.', NULL, '2026-10-20 08:27:49.790548+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
