INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3107, 294, 'comment', 'owner', 'Step 2 done: the sweep test runs inside yarn validate and fails on any Text or Animated.Text carrying opacity in its own or animated style, and on any text colour whose alpha is neither 0 nor 1 - proven red by a planted opacity-0.5 Text and a planted half-alpha colour before landing green. The eight suites the prototype left red now assert the state-matrix solids (colours, not opacity), with the locked-on branch newly rendered and the sound row''s countdown asserted as presence. yarn validate is green on lane/294 (1898bdc3, 2.4.13). Left: Step 3, the three resting-hidden fades, now underway in this lane.', NULL, '2026-10-21 15:04:06.175268+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
