INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3117, 294, 'comment', 'owner', 'Owner''s read on the iPhone XS mock (3427a3b0, 2.4.15), dictated 2026-10-24: the Arabic overlap band is gone - the ticket''s own fix reads right on the glass. Same build carries a regression: every prayer row has lost its time column (name then bell, nothing between, bell packed left), so the rest of the read list waits on the fix. Row back In progress on the owner''s order to drive the XS directly with a hot-reload dev build.', NULL, '2026-10-24 03:14:36.414279+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
