INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3507, 368, 'comment', 'owner', 'Owner order (2026-10-25, dictated): the store builds were compiled on EAS and sit awaiting review by Google and Apple; while that pends, download the production artifacts from EAS through the expo MCP and install them on the iPhone and the Android phone, so the owner confirms what users will get before releasing to the public. Not a local build. EAS use stays read-only: list and download only, never build, never push, never submit.', NULL, '2026-10-25 14:03:02.498932+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
