INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3546, 346, 'comment', 'owner', 'Plan-conformance review of the two commits: the diff matches the plan exactly - the spacing gate over all six catalogs with the string-edge rule, the one-space Thai fix, the exported badge with numberOfLines={1} and nothing else moved, the six-locale pin grown additively, and the version bumps as ordered. Both suites run green here and the claimed-untouched files are untouched. It conforms; nothing to fix.', NULL, '2026-10-25 14:22:07.978122+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
