INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3557, 368, 'comment', 'owner', 'Owner order (2026-10-25, dictated): the downloads stand by, NOT installed - the install and the on-glass smoke happen when the owner returns and says so. Download both artifacts, verify them desk-side (versions, identifiers, aapt2 badging on the APK, the IPA''s info, checksums), record everything on the ticket, then park: the two phones are released to the board''s other tickets meanwhile. If an install already began before this order landed, stop after the current act, record exactly what state each phone is in, and restore standby where you can without destroying anything.', NULL, '2026-10-25 14:43:08.163284+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
