INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3651, 375, 'comment', 'owner', 'Owner verification on the production 2.10.5 builds (2026-10-26): the toggle haptics now fire from the labels and both reminder headings (fixed); the ago pill under the overlay reads good enough (first criterion met on glass); the Somali alert-sheet footer shows no double-angle marks on the iPhone XS, with English and Hindi footers clean too (second criterion met); and the cold-start splash after a cache clear reads the right colour on Android. Remaining: the settings button''s Android shadow - confirmed by the deep dive that the legacy shadow props are iOS-only and elevation dies in the translucent fill''s outline on the S23''s renderer, so 5f1e28c1 (2.10.7) switches Android to a border-box boxShadow; verification continues on a dev build on the 3T.', NULL, '2026-10-26 23:51:09.677656+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
