INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3871, 396, 'comment', 'owner', 'Plan written, grilled and refreshed: the T-396 doc (docs page 45) - the failed check gets its own result field and the row its fourth state (red circle, white X, ring kept, retryable), the once-per-opening budget is consumed only by a verdict, and the six-locale failure copy is drafted for the owner''s glass read. The griller''s two findings (the empty-results stamp and the default-mock wording) are folded in. Gated to Ready at 6 points (1 docs + 2 code + 3 device).', NULL, '2026-10-27 16:29:38.315431+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
